const currencies=[['USD','미국 달러','🇺🇸'],['EUR','유로','🇪🇺'],['KRW','대한민국 원','🇰🇷'],['JPY','일본 엔','🇯🇵'],['CNY','중국 위안','🇨🇳'],['GBP','영국 파운드','🇬🇧'],['THB','태국 바트','🇹🇭'],['VND','베트남 동','🇻🇳'],['TWD','대만 달러','🇹🇼'],['HKD','홍콩 달러','🇭🇰'],['SGD','싱가포르 달러','🇸🇬'],['AUD','호주 달러','🇦🇺'],['CAD','캐나다 달러','🇨🇦'],['CHF','스위스 프랑','🇨🇭'],['NZD','뉴질랜드 달러','🇳🇿'],['PHP','필리핀 페소','🇵🇭'],['IDR','인도네시아 루피아','🇮🇩'],['MYR','말레이시아 링깃','🇲🇾'],['INR','인도 루피','🇮🇳'],['AED','아랍에미리트 디르함','🇦🇪'],['TRY','튀르키예 리라','🇹🇷'],['MXN','멕시코 페소','🇲🇽'],['SEK','스웨덴 크로나','🇸🇪'],['ZAR','남아공 랜드','🇿🇦']];
const $=id=>document.getElementById(id),from=$('from'),to=$('to'),amount=$('amount');let data=null,failed=false,busy=false,installPrompt=null;
function read(key){try{return JSON.parse(localStorage.getItem(key))}catch{return null}}function save(key,v){try{localStorage.setItem(key,JSON.stringify(v))}catch{}}
const prefs=read('pw-prefs');for(const el of [from,to])for(const [code,name,flag]of currencies){const option=document.createElement('option');option.value=code;option.textContent=`${flag} ${code} · ${name}`;el.append(option)}from.value=currencies.some(c=>c[0]===prefs?.from)?prefs.from:'USD';to.value=currencies.some(c=>c[0]===prefs?.to)?prefs.to:'KRW';amount.value=/^\d{1,16}(\.\d{0,15})?$/.test(prefs?.amount)?prefs.amount:'100';
const cached=read('pw-rates');if(cached?.rates&&currencies.every(c=>Number.isFinite(cached.rates[c[0]])&&cached.rates[c[0]]>0)&&Number.isFinite(cached.time_last_update_unix))data=cached;
const format=(n,code)=>new Intl.NumberFormat('ko-KR',{maximumFractionDigits:['KRW','JPY','VND','IDR'].includes(code)?0:2}).format(n);
function update(){const value=Number(amount.value||0);const ratio=from.value===to.value?1:data?data.rates[to.value]/data.rates[from.value]:null;$('result').textContent=ratio===null?'—':format(value*ratio,to.value);$('rate').textContent=ratio===null?'환율 연결 후 계산할 수 있어요':`1 ${from.value} = ${new Intl.NumberFormat('ko-KR',{maximumFractionDigits:5}).format(ratio)} ${to.value}`;save('pw-prefs',{from:from.value,to:to.value,amount:amount.value});document.querySelectorAll('.destination').forEach(b=>b.classList.toggle('active',b.dataset.code===from.value));showStatus()}
function showStatus(){const old=data&&(Date.now()/1000-data.time_last_update_unix>172800);$('status').textContent=data?`${failed||!navigator.onLine?'저장 환율 사용 · ':old?'오래된 환율 · ':'최신 조회 · '}${new Date(data.time_last_update_unix*1000).toLocaleString('ko-KR',{month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit'})} 기준`:'환율 연결이 필요해요 · 새로고침을 눌러주세요';$('saved').textContent=busy?'조회 중…':failed?'연결 확인':'자동 저장';}
async function refresh(){if(busy)return;busy=true;$('refresh').disabled=true;showStatus();try{const res=await fetch('https://open.er-api.com/v6/latest/USD',{cache:'no-store',signal:AbortSignal.timeout(12000)});if(!res.ok)throw Error('HTTP');const d=await res.json();if(d.result!=='success'||!Number.isFinite(d.time_last_update_unix)||!currencies.every(c=>Number.isFinite(d.rates?.[c[0]])&&d.rates[c[0]]>0))throw Error('Invalid rates');data=d;failed=false;save('pw-rates',d)}catch{failed=true}finally{busy=false;$('refresh').disabled=false;update()}}
from.onchange=to.onchange=update;amount.oninput=()=>{amount.value=amount.value.replace(/[^\d.]/g,'').replace(/\./g,((seen=false)=>()=>seen?'':(seen=true,'.'))()).slice(0,16);if(!Number.isFinite(Number(amount.value)))amount.value='0';update()};$('swap').onclick=()=>{const a=from.value;from.value=to.value;to.value=a;update()};$('refresh').onclick=refresh;
for(const key of ['1','2','3','4','5','6','7','8','9','C','0','.','⌫']){if(key==='.')continue;const b=document.createElement('button');b.textContent=key;b.setAttribute('aria-label',key==='C'?'금액 지우기':key==='⌫'?'한 자리 지우기':key);b.onclick=()=>{amount.value=key==='C'?'0':key==='⌫'?(amount.value.slice(0,-1)||'0'):(amount.value==='0'?key:amount.value+key).slice(0,16);update()};$('keypad').append(b)}
// Keep a familiar 3 × 4 keypad, with decimal input on the last row.
const clear=$('keypad').querySelectorAll('button')[9];clear.textContent='AC';const decimal=document.createElement('button');decimal.textContent='.';decimal.setAttribute('aria-label','소수점');decimal.onclick=()=>{if(!amount.value.includes('.')&&amount.value.length<16){amount.value+='.';update()}};$('keypad').insertBefore(decimal,clear);clear.remove();const back=$('keypad').lastElementChild;back.oncontextmenu=e=>{e.preventDefault();amount.value='0';update()};const reset=document.createElement('button');reset.textContent='초기화';reset.className='reset';reset.onclick=()=>{amount.value='0';update()};document.querySelector('.presets').append(reset);
document.querySelectorAll('[data-add]').forEach(b=>b.onclick=()=>{const n=Number(amount.value||0)+Number(b.dataset.add);if(n<1e15){amount.value=String(n);update()}});
for(const [code,country]of [['USD','미국'],['EUR','유럽'],['JPY','일본'],['THB','태국'],['VND','베트남'],['TWD','대만']]){const c=currencies.find(c=>c[0]===code);const b=document.createElement('button');b.className='destination';b.dataset.code=code;b.innerHTML=`<span class="flag">${c[2]}</span><b>${country}</b><small>${code} ${c[1].split(' ').at(-1)}</small>`;b.onclick=()=>{from.value=code;to.value='KRW';update()};$('destinations').append(b)}
$('install').onclick=async()=>{if(installPrompt){await installPrompt.prompt();installPrompt=null}else $('guide').showModal()};window.addEventListener('beforeinstallprompt',e=>{e.preventDefault();installPrompt=e});for(const id of ['close','done'])$(id).onclick=()=>$('guide').close();$('guide').addEventListener('click',e=>{if(e.target===$('guide')){const r=$('guide').getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)$('guide').close()}});window.addEventListener('online',refresh);window.addEventListener('offline',showStatus);document.addEventListener('visibilitychange',()=>{if(!document.hidden)refresh()});setInterval(refresh,15*60*1000);if('serviceWorker'in navigator)navigator.serviceWorker.register('./sw.js').catch(()=>{});update();refresh();
